  shipmentStatusLogs              ecommerce_mall_shipment_status_log_of_customers[]
  reviews                         ecommerce_mall_reviews[]
  reviewSnapshots                 ecommerce_mall_review_snapshots[]
  reviewHelpfulVotes              ecommerce_mall_review_helpful_votes[]
  reviewDeletions                 ecommerce_mall_review_deletions[]
  reviewOrderConstraints          ecommerce_mall_review_order_constraints[]
  cancellationRequests            ecommerce_mall_cancellation_requests[]
  refundRequests                  ecommerce_mall_refund_requests[]
  refundRequestSnapshots          ecommerce_mall_refund_request_snapshots[]
  administratorRequestSubmissions ecommerce_mall_administrator_request_customers[]
  administratorActionLogs         ecommerce_mall_administrator_action_logs[]
  bans                            ecommerce_mall_administrator_customer_bans[]
  platformOversightLogs           ecommerce_mall_administrator_platform_oversight_logs[]
  administratorDecisionRecords    ecommerce_mall_administrator_decision_records[]

